// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 948, H = 600;
draw.viewbox(0, 0, W, H);

var teal = '#007c9f';
var black = '#000000';
var gridStroke = '#111111';
var accent = '#d8891c';

var left = { cx: 240, cy: 230, R: 184, unit: 146, name: 'left' };
var right = { cx: 720, cy: 230, R: 184, unit: 146, name: 'right' };

var gridLayer = draw.group();
var curveLayer = draw.group();
var labelLayer = draw.group();

var dynamicCurveGroup = curveLayer.group();
var dynamicMarkerGroup = curveLayer.group();
var dynamicLabelGroup = labelLayer.group();

var currentN = 4;
var currentA = 1;
var currentForm = 'cos';
var rFn = function(theta, a, n) { return a * Math.cos(n * theta); };
var customMode = false;
var currentStep = 0;
var bindingsReady = false;
var aBinding, nBinding, rBinding;

function polarPoint(panel, radius, theta) {
  return [
    panel.cx + panel.unit * radius * Math.cos(theta),
    panel.cy - panel.unit * radius * Math.sin(theta)
  ];
}

function makeArrowHead(group, x, y, angle, size) {
  var p1 = [x + size * Math.cos(angle), y - size * Math.sin(angle)];
  var p2 = [x + size * 0.72 * Math.cos(angle + Math.PI * 0.78), y - size * 0.72 * Math.sin(angle + Math.PI * 0.78)];
  var p3 = [x + size * 0.72 * Math.cos(angle - Math.PI * 0.78), y - size * 0.72 * Math.sin(angle - Math.PI * 0.78)];
  group.polygon(p1[0] + ',' + p1[1] + ' ' + p2[0] + ',' + p2[1] + ' ' + p3[0] + ',' + p3[1]).fill(black).stroke('none');
}

function drawPolarGrid(panel) {
  var g = gridLayer.group();
  var dash = '1.1 3.1';

  for (var i = 1; i <= 5; i++) {
    g.circle(2 * panel.R * i / 5)
      .center(panel.cx, panel.cy)
      .fill('none')
      .stroke({ color: gridStroke, width: 1, dasharray: dash });
  }

  for (var k = 0; k < 8; k++) {
    var th = k * Math.PI / 4;
    var x1 = panel.cx - panel.R * Math.cos(th);
    var y1 = panel.cy + panel.R * Math.sin(th);
    var x2 = panel.cx + panel.R * Math.cos(th);
    var y2 = panel.cy - panel.R * Math.sin(th);
    g.line(x1, y1, x2, y2).stroke({ color: gridStroke, width: 0.9, dasharray: dash });
  }

  var ext = panel.R + 34;
  g.line(panel.cx - ext, panel.cy, panel.cx + ext, panel.cy).stroke({ color: black, width: 2 });
  g.line(panel.cx, panel.cy - ext, panel.cx, panel.cy + ext).stroke({ color: black, width: 2 });

  makeArrowHead(g, panel.cx + ext + 18, panel.cy, 0, 22);
  makeArrowHead(g, panel.cx - ext - 18, panel.cy, Math.PI, 22);
  makeArrowHead(g, panel.cx, panel.cy - ext - 18, Math.PI / 2, 22);
  makeArrowHead(g, panel.cx, panel.cy + ext + 18, -Math.PI / 2, 22);

  g.circle(5.5).center(panel.cx, panel.cy).fill(black).opacity(0.95);
  return g;
}

function rosePolyline(panel, fn, a, n, samples) {
  var pts = [];
  for (var i = 0; i <= samples; i++) {
    var theta = 2 * Math.PI * i / samples;
    var r = fn(theta, a, n);
    if (!isFinite(r)) continue;
    var p = polarPoint(panel, r, theta);
    pts.push(p[0].toFixed(2) + ',' + p[1].toFixed(2));
  }
  return pts.join(' ');
}

function drawStaticRose(panel, form, n, a) {
  var fn = form === 'sin'
    ? function(theta, aa, nn) { return aa * Math.sin(nn * theta); }
    : function(theta, aa, nn) { return aa * Math.cos(nn * theta); };
  var line = curveLayer.polyline(rosePolyline(panel, fn, a, n, 2400))
    .fill('none')
    .stroke({ color: teal, width: 4.2, linecap: 'round', linejoin: 'round' });
  line.css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip((form === 'sin' ? 'Sine' : 'Cosine') + ' rose: n = ' + n + ', ' + (n % 2 === 0 ? (2 * n) : n) + ' petals', e); })
    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() {
      showPopup('Reference rose', 'This textbook reference shows the petal-count rule. Odd n makes n petals; even n makes 2n petals.');
    });
}

function labelText(txt, x, y, size, italic, anchor) {
  return labelLayer.text(txt)
    .font({ family: 'Times New Roman, serif', size: size, anchor: anchor || 'middle' })
    .attr({
      'font-style': italic ? 'italic' : 'normal',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    })
    .fill(black)
    .move(x, y);
}

function addCaption(panel, text, y, id) {
  var t = labelText(text, panel.cx, y, 34, true, 'middle');
  if (id) t.attr('id', id);
  return t;
}

drawPolarGrid(left);
drawPolarGrid(right);
