labelText('(b)', right.cx, 535, 38, false, 'middle');

function petalCount(n) {
  var m = Math.max(0, Math.abs(Math.round(n)));
  if (m === 0) return 0;
  return (m % 2 === 0) ? 2 * m : m;
}

function redrawDynamic() {
  if (!dynamicCurveGroup) return;

  dynamicCurveGroup.clear();
  dynamicMarkerGroup.clear();
  dynamicLabelGroup.clear();

  var pts = rosePolyline(left, rFn, currentA, currentN, 3000);
