      showTooltip('Current polar rose: parity of n gives the petal count.', e);
    })
    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() {
      showPopup('Current rose curve', 'The curve is sampled directly from r(θ). Changing n changes how often the radius oscillates as θ goes around the circle, which is why parity controls the number of petals.');
    });

  dynamicMarkerGroup.circle(6).center(left.cx, left.cy).fill(black);

  var maxAbs = -1, maxTheta = 0, maxR = 0;
  for (var i = 0; i <= 1440; i++) {
    var th = 2 * Math.PI * i / 1440;
    var rv = rFn(th, currentA, currentN);
