      .on('mousemove', function(e) { showTooltip('The farthest point on a petal has radius a.', e); })
      .on('mouseleave', function() { hideTooltip(); })
      .on('click', function() { showPopup('Amplitude a', 'The coefficient a sets the maximum radius. It scales the rose outward or inward without changing the petal count.'); });
  }

  var roundedN = Math.round(currentN);
  var count = petalCount(currentN);
  var countText = (Math.abs(currentN - roundedN) < 1e-8)
    ? (count + (count === 1 ? ' petal' : ' petals'))
