    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() { showPopup('Petal-count rule', 'For rose curves r = a cos(nθ) and r = a sin(nθ), odd n gives n petals, while even n gives 2n petals. Sine and cosine mainly rotate the pattern.'); });

  leftCaption.text(currentForm === 'sin' ? 'r = a sin(nθ)' : 'r = a cos(nθ)');
}

