function polarPoint(panel, radius, theta) {
  return [
    panel.cx + panel.unit * radius * Math.cos(theta),
    panel.cy - panel.unit * radius * Math.sin(theta)
  ];
}

function arrowHead(group, x, y, angle, size) {
  var spread = 0.43;
  var p1 = [x, y];
  var p2 = [x + size * Math.cos(angle + Math.PI - spread), y - size * Math.sin(angle + Math.PI - spread)];
  var p3 = [x + size * Math.cos(angle + Math.PI + spread), y - size * Math.sin(angle + Math.PI + spread)];
  group.polygon(p1[0] + ',' + p1[1] + ' ' + p2[0] + ',' + p2[1] + ' ' + p3[0] + ',' + p3[1])
    .fill(black)
    .stroke('none');
}

function drawPolarGrid(panel) {
  var g = gridLayer.group();
  var dash = '1.3 3.3';

  for (var i = 1; i <= 5; i++) {
    g.circle(2 * panel.R * i / 5)
      .center(panel.cx, panel.cy)
      .fill('none')
      .stroke({ color: gridStroke, width: 1.05, dasharray: dash, linecap: 'round' });
  }

  for (var k = 0; k < 8; k++) {
    var th = k * Math.PI / 4;
    var x1 = panel.cx - panel.R * Math.cos(th);
    var y1 = panel.cy + panel.R * Math.sin(th);
    var x2 = panel.cx + panel.R * Math.cos(th);
    var y2 = panel.cy - panel.R * Math.sin(th);
    g.line(x1, y1, x2, y2)
      .stroke({ color: gridStroke, width: 0.95, dasharray: dash, linecap: 'round' });
  }

  var axisLen = panel.R + 28;
  var arrowGap = 14;
  var tipSize = 19;

  g.line(panel.cx - axisLen, panel.cy, panel.cx + axisLen, panel.cy)
    .stroke({ color: black, width: 2.25, linecap: 'butt' });
  g.line(panel.cx, panel.cy - axisLen, panel.cx, panel.cy + axisLen)
    .stroke({ color: black, width: 2.25, linecap: 'butt' });

  arrowHead(g, panel.cx + axisLen + arrowGap, panel.cy, 0, tipSize);
  arrowHead(g, panel.cx - axisLen - arrowGap, panel.cy, Math.PI, tipSize);
  arrowHead(g, panel.cx, panel.cy - axisLen - arrowGap, Math.PI / 2, tipSize);
  arrowHead(g, panel.cx, panel.cy + axisLen + arrowGap, -Math.PI / 2, tipSize);

  g.circle(4.7).center(panel.cx, panel.cy).fill(black).opacity(0.96);
