    var theta = 2 * Math.PI * i / samples;
    var r = roseR(panel.form, panel.n, theta);
    var p = polarPoint(panel, r, theta);
    pts.push(p[0].toFixed(2) + ',' + p[1].toFixed(2));
  }
  return pts.join(' ');
}

