userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span id="demoNarration" style="margin:0;font-size:10px;line-height:1.35;max-width:260px">Start with a clean replica of the original two-panel figure: an even-n cosine rose on the left and an odd-n sine rose on the right. No added markers or annotations are shown.</span><span style="display:flex;align-items:center;gap:6px"><button onclick="prevStep()">◀</button><span id="stepLabel">1 / 3</span><button onclick="nextStep()">▶</button></span><label>Explanatory overlays<select id="explanationViewInput" onchange="update_explanationView(this.value)"><option selected>Textbook figure</option><option>Petal-count rule</option><option>Sine vs cosine orientation</option></select></label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 945, H = 577;
draw.viewbox(0, 0, W, H);

var teal = '#007c9f';
var black = '#000000';
var gridStroke = '#4f4f4f';
var overlayOrange = '#d8891c';
var overlayBlue = '#007c9f';

draw.rect(W, H).fill('#ffffff');

var left = { cx: 228, cy: 228, R: 183, unit: 147, n: 4, form: 'cos' };
var right = { cx: 714, cy: 228, R: 183, unit: 147, n: 3, form: 'sin' };

var gridLayer = draw.group();
var curveLayer = draw.group();
var overlayLayer = draw.group();
var captionLayer = draw.group();

var currentView = 'Textbook figure';
var currentStep = 0;

function polarPoint(panel, radius, theta) {
  return [
    panel.cx + panel.unit * radius * Math.cos(theta),
    panel.cy - panel.unit * radius * Math.sin(theta)
  ];
}

function screenPolar(panel, dist, theta) {
  return [
    panel.cx + dist * Math.cos(theta),
    panel.cy - dist * Math.sin(theta)
  ];
}

function arrowHead(group, x, y, screenAngle, length, halfWidth) {
  var bx = x - length * Math.cos(screenAngle);
  var by = y - length * Math.sin(screenAngle);
  var nx = -Math.sin(screenAngle);
  var ny = Math.cos(screenAngle);
  var pts = [
    [x, y],
    [bx + halfWidth * nx, by + halfWidth * ny],
    [bx - halfWidth * nx, by - halfWidth * ny]
  ];
  group.polygon(pts.map(function(p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
    .fill(black)
    .stroke('none');
}

function drawAxisWithArrows(g, x1, y1, x2, y2, angleForward, angleBack) {
  g.line(x1, y1, x2, y2)
    .stroke({ color: black, width: 2.15, linecap: 'butt' });
  arrowHead(g, x2, y2, angleForward, 23, 8.4);
  arrowHead(g, x1, y1, angleBack, 23, 8.4);
}

function drawPolarGrid(panel) {
  var g = gridLayer.group();
  var dash = '1.1 3.0';

  for (var i = 1; i <= 5; i++) {
    g.circle(2 * panel.R * i / 5)
      .center(panel.cx, panel.cy)
      .fill('none')
      .stroke({ color: gridStroke, width: 0.95, dasharray: dash, linecap: 'round' });
  }

  for (var k = 0; k < 8; k++) {
    var th = k * Math.PI / 4;
    var a = screenPolar(panel, -panel.R, th);
    var b = screenPolar(panel, panel.R, th);
    g.line(a[0], a[1], b[0], b[1])
      .stroke({ color: gridStroke, width: 0.85, dasharray: dash, linecap: 'round' });
  }

  var tip = panel.R + 45;
  drawAxisWithArrows(g, panel.cx - tip, panel.cy, panel.cx + tip, panel.cy, 0, Math.PI);
  drawAxisWithArrows(g, panel.cx, panel.cy + tip, panel.cx, panel.cy - tip, -Math.PI / 2, Math.PI / 2);
}

function roseR(form, n, theta) {
  return form === 'sin' ? Math.sin(n * theta) : Math.cos(n * theta);
}

function rosePolyline(panel, samples) {
  var pts = [];
  for (var i = 0; i <= samples; i++) {
    var theta = 2 * Math.PI * i / samples;
    var r = roseR(panel.form, panel.n, theta);
    var p = polarPoint(panel, r, theta);
    pts.push(p[0].toFixed(2) + ',' + p[1].toFixed(2));
  }
  return pts.join(' ');
}

function drawRose(panel, tooltipLabel) {
  var rose = curveLayer.polyline(rosePolyline(panel, 3000))
    .fill('none')
    .stroke({ color: teal, width: 4.35, linecap: 'round', linejoin: 'round' });

  rose.css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip(tooltipLabel, e); })
    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() {
      showPopup('Polar rose', 'This curve is traced from r = a ' + panel.form + '(nθ). The comparison shows the petal-count rule: even n gives 2n petals, while odd n gives n petals.');
    });
}

function captionText(text, x, y, size, italic) {
  return captionLayer.text(text)
    .font({ family: 'Times New Roman, Times, serif', size: size, anchor: 'middle' })
    .attr({
      x: x,
      y: y,
      'dominant-baseline': 'middle',
      'font-style': italic ? 'italic' : 'normal',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    })
    .fill(black);
}

function overlayLabel(group, text, x, y, color, size) {
  var t = group.text(text)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size || 18, anchor: 'middle' })
    .attr({
      x: x,
      y: y,
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 5,
      'stroke-linejoin': 'round'
    })
    .fill(color || '#333333');
  var box = group.rect(Math.max(138, text.length * (size || 18) * 0.53), (size || 18) + 12)
    .radius(7)
    .center(x, y)
    .fill('#ffffff')
    .opacity(0.84);
  box.back();
  return t;
}

function addPetalTipRings(group, panel, angles, color) {
  for (var i = 0; i < angles.length; i++) {
    var p = polarPoint(panel, 1, angles[i]);
    group.circle(13)
      .center(p[0], p[1])
      .fill('#ffffff')
      .opacity(0.78)
      .stroke({ color: color, width: 2.5 });
  }
}

function addPetalOverlay() {
  var g = overlayLayer.group();

  overlayLabel(g, 'even n → 2n petals', left.cx, 30, '#333333', 18);
  overlayLabel(g, '8 petals', left.cx, 55, overlayBlue, 17);
  overlayLabel(g, 'odd n → n petals', right.cx, 30, '#333333', 18);
  overlayLabel(g, '3 petals', right.cx, 55, overlayBlue, 17);

  var leftAngles = [];
  for (var k = 0; k < 8; k++) leftAngles.push(k * Math.PI / 4);
  addPetalTipRings(g, left, leftAngles, overlayBlue);
  addPetalTipRings(g, right, [Math.PI / 6, 5 * Math.PI / 6, 3 * Math.PI / 2], overlayBlue);

  g.css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip('The parity of n determines the number of petals.', e); })
    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() {
      showPopup('Petal-count rule', 'For r = a cos(nθ) or r = a sin(nθ), an even integer n produces 2n petals. An odd integer n produces n petals.');
    });
}

function guideRay(group, panel, theta, color) {
  var a = screenPolar(panel, -panel.R * 0.92, theta);
  var b = screenPolar(panel, panel.R * 0.92, theta);
  group.line(a[0], a[1], b[0], b[1])
    .stroke({ color: color, width: 2.2, dasharray: '8 6', linecap: 'round' })
    .opacity(0.78);
}

function addOrientationOverlay() {
  var g = overlayLayer.group();

  guideRay(g, left, 0, overlayOrange);
  guideRay(g, left, Math.PI / 2, overlayOrange);

  guideRay(g, right, Math.PI / 6, overlayOrange);
  guideRay(g, right, 5 * Math.PI / 6, overlayOrange);
  guideRay(g, right, 3 * Math.PI / 2, overlayOrange);

  overlayLabel(g, 'cosine petals align with axes', left.cx, 34, overlayOrange, 17);
  overlayLabel(g, 'sine petals are rotated', right.cx, 34, overlayOrange, 17);

  g.css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip('Sine and cosine mainly rotate the rose; parity still controls petal count.', e); })
    .on('mouseleave', function() { hideTooltip(); })
    .on('click', function() {
      showPopup('Orientation', 'Cosine roses place a petal on the polar axis when θ = 0. Sine roses are rotated because their maximum radius occurs at a different angle.');
    });
}

function updateOverlays() {
  overlayLayer.clear();
  if (currentView === 'Petal-count rule') addPetalOverlay();
  if (currentView === 'Sine vs cosine orientation') addOrientationOverlay();
}

function update_explanationView(v) {
  currentView = v;
  var select = document.getElementById('explanationViewInput');
  if (select) select.value = v;
  updateOverlays();
}

var demoSteps = [
  {
    title: 'Textbook figure',
    narration: 'Start with a clean replica of the original two-panel figure: an even-n cosine rose on the left and an odd-n sine rose on the right. No added markers or annotations are shown.',
    state: { explanationView: 'Textbook figure' }
  },
  {
    title: 'Petal-count rule',
    narration: 'Turn on the petal-count overlay to see the key contrast: the even-n rose has twice as many petals, while the odd-n rose has exactly n petals.',
    state: { explanationView: 'Petal-count rule' }
  },
  {
    title: 'Orientation difference',
    narration: 'Switch to the orientation overlay to compare how cosine and sine place the petals differently on the same kind of polar grid.',
    state: { explanationView: 'Sine vs cosine orientation' }
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var narration = document.getElementById('demoNarration');
  var stepLabel = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (stepLabel) stepLabel.textContent = (currentStep + 1) + ' / ' + demoSteps.length;
  update_explanationView(step.state.explanationView);
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

drawPolarGrid(left);
drawPolarGrid(right);
drawRose(left, 'Left panel: r = a cos(nθ) with even n, producing 2n petals.');
drawRose(right, 'Right panel: r = a sin(nθ) with odd n, producing n petals.');

captionText('r = a cos(nθ), n even', left.cx, 488, 36, true);
captionText('(a)', left.cx, 548, 38, false);
captionText('r = a sin(nθ), n odd', right.cx, 488, 36, true);
captionText('(b)', right.cx, 548, 38, false);

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

